// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *SectionVersionClient) MapCreateBulk(slice any, setFunc func(*SectionVersionCreate, int)) *SectionVersionCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &SectionVersionCreateBulk{err: fmt.Errorf("calling to SectionVersionClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*SectionVersionCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &SectionVersionCreateBulk{config: c.config, builders: builders}
}

